@app.get("/api/view")
def view_image(filename: str, type: str = "input", subfolder: str = ""):
    # 先按原逻辑去各 ComfyUI 后端找
    for addr in COMFYUI_INSTANCES:
        try:
            url = f"http://{addr}/view"
            params = {"filename": filename, "type": type, "subfolder": subfolder}
            r = _NO_PROXY_SESSION.get(url, params=params, timeout=1)
            if r.status_code == 200:
                return Response(content=r.content, media_type=r.headers.get('Content-Type'))
        except Exception:
            continue
    # 后端都拿不到时回退本地 assets/<input|output>/
    # 适用场景：画布通过 /api/ai/upload 把参考图直接落到本地 assets/input/，
    # 但 ComfyUI 的 input 可能因为重启/清理而丢失，导致 enhance/klein 等页面预览对比图 404
    if not subfolder and type in ("input", "output"):
        safe_name = os.path.basename(filename or "")
        if safe_name:
            local_path = output_path_for(safe_name, "input" if type == "input" else "output")
            if os.path.isfile(local_path):
                return FileResponse(local_path, media_type=content_type_for_path(local_path))
    raise HTTPException(status_code=404, detail="Image not found on any available backend")

@app.get("/api/download-output")
def download_output(request: Request, url: str, name: str = "", inline: bool = False):
    url = rewrite_runninghub_file_url(url)
    path = output_file_from_url(url)
    if not path:
        path = local_media_file_by_basename(filename_from_media_url(url, ""))
    if path:
        filename = sanitize_export_filename(os.path.basename(name) if name else os.path.basename(path), os.path.basename(path))
        return FileResponse(path, media_type=content_type_for_path(path), filename=None if inline else filename)
    # 远程文件：流式代理，绝不把整段视频/大文件读进内存（否则多个视频同时代理会撑爆内存、拖垮单进程服务）。
    parsed = urllib.parse.urlparse(str(url or "").strip())
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise HTTPException(status_code=400, detail="无效的下载地址")
    try:
        upstream_headers = {"User-Agent": "ComfyUI-API-Modelscope/1.0"}
        range_header = request.headers.get("range")
        if range_header:
            upstream_headers["Range"] = range_header
        upstream = _NO_PROXY_SESSION.get(
            url, stream=True, timeout=(10, 60),
            headers=upstream_headers,
        )
        upstream.raise_for_status()
    except requests.RequestException as exc:
        raise HTTPException(status_code=502, detail=f"远程文件下载失败：{exc}")
    content_type = upstream.headers.get("content-type") or "application/octet-stream"
    fallback = filename_from_media_url(url, "download.bin")
    filename = sanitize_export_filename(os.path.basename(name) if name else fallback, fallback)
    disposition = "inline" if inline else "attachment"
    headers = {"Content-Disposition": f"{disposition}; filename*=UTF-8''{urllib.parse.quote(filename)}"}
    content_length = upstream.headers.get("content-length")
    if content_length:
        headers["Content-Length"] = content_length
    for key in ("content-range", "accept-ranges"):
        value = upstream.headers.get(key)
        if value:
            headers["-".join(part.capitalize() for part in key.split("-"))] = value

    def stream_remote():
        try:
            for chunk in upstream.iter_content(chunk_size=256 * 1024):
                if chunk:
                    yield chunk
        finally:
            upstream.close()

    return StreamingResponse(stream_remote(), media_type=content_type, headers=headers, status_code=upstream.status_code)

@app.post("/api/upload")
async def upload_image(files: List[UploadFile] = File(...)):
    uploaded_files = []
    files_content = []
    for file in files:
        content = await file.read()
        files_content.append((file, content))

    for file, content in files_content:
        success_count = 0
        last_result = None
        for addr in COMFYUI_INSTANCES:
            try:
                files_data = {'image': (file.filename, content, file.content_type)}
                response = _NO_PROXY_SESSION.post(f"http://{addr}/upload/image", files=files_data, timeout=5)
                if response.status_code == 200:
                    last_result = response.json()
                    success_count += 1
            except Exception as e:
                print(f"Upload error for {addr}: {e}")

        if success_count > 0 and last_result:
            uploaded_files.append({"comfy_name": last_result.get("name", file.filename)})
        else:
            raise HTTPException(status_code=500, detail="Failed to upload to any backend")

    return {"files": uploaded_files}

@app.post("/api/ai/upload")
async def upload_ai_reference(files: List[UploadFile] = File(...)):
    uploaded = []
    image_exts = {".png", ".jpg", ".jpeg", ".webp", ".gif"}
    video_exts = {".mp4", ".webm", ".mov", ".m4v", ".flv"}
    audio_exts = {".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac"}
    doc_exts = {".pdf", ".txt", ".md", ".markdown", ".doc", ".docx", ".xls", ".xlsx", ".csv", ".json", ".zip", ".yaml", ".yml", ".log"}
    max_upload_bytes = 50 * 1024 * 1024
    for file in files:
        content = await file.read()
        if not content:
            continue
        if len(content) > max_upload_bytes:
            raise HTTPException(status_code=413, detail=f"{file.filename or '文件'} 超过 50MB，无法上传")
        ext = os.path.splitext(file.filename or "")[1].lower()
        content_type = (file.content_type or "").lower()
        kind = "image"
        if ext in video_exts or content_type.startswith("video/"):
            kind = "video"
            if ext not in video_exts:
                ext = ".webm" if "webm" in content_type else ".mov" if "quicktime" in content_type else ".mp4"
        elif ext in audio_exts or content_type.startswith("audio/"):
            kind = "audio"
            if ext not in audio_exts:
                ext = ".wav" if "wav" in content_type else ".ogg" if "ogg" in content_type else ".m4a" if "mp4" in content_type else ".mp3"
        elif ext in image_exts or content_type.startswith("image/"):
            kind = "image"
            if ext not in image_exts:
                ext = ".jpg" if "jpeg" in content_type else ".webp" if "webp" in content_type else ".gif" if "gif" in content_type else ".png"
        elif ext in doc_exts or content_type.startswith(("text/", "application/")):
            kind = "file"
            if not ext:
                ext = mimetypes.guess_extension(content_type) or ".bin"
        else:
            kind = "file"
            if not ext:
                ext = ".bin"
        filename = f"ai_ref_{uuid.uuid4().hex[:12]}{ext}"
        path = output_path_for(filename, "input")
        with open(path, "wb") as f:
            f.write(content)
        uploaded.append({"url": output_url_for(filename, "input"), "name": file.filename or filename, "kind": kind, "mime": content_type})
    return {"files": uploaded}

class VideoBlurFacesRequest(BaseModel):
    url: str = ""            # 本地视频 URL（/assets/ 或 /output/ 开头）
    strength: int = 60       # 高斯模糊核大小（20-100，越大越糊）

@app.post("/api/video/blur-faces")
async def video_blur_faces(payload: VideoBlurFacesRequest):
    """检测视频中的人脸并高斯模糊，规避平台真人审核拦截。
    返回模糊后的视频 URL（存 assets/input/blurred_*.mp4）。
    人脸检测用 YuNet 模型（assets/models/face_detection_yunet.onnx），
    无模型时返回 400 提示；无 ffmpeg 时返回 400 提示。"""
    raw_url = (payload.url or "").strip()
    if not raw_url:
        raise HTTPException(status_code=400, detail="缺少视频 URL")
    src_path = output_file_from_url(raw_url)
    if not src_path or not os.path.isfile(src_path):
        raise HTTPException(status_code=404, detail="视频文件不存在")
    if os.path.getsize(src_path) > 200 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="视频超过 200MB，请先压缩")
    strength = max(20, min(100, int(payload.strength or 60)))
    ks = strength if strength % 2 == 1 else strength + 1

    model_path = os.path.join(BASE_DIR, "assets", "models", "face_detection_yunet.onnx")
    if not os.path.isfile(model_path):
        raise HTTPException(status_code=400, detail="人脸检测模型缺失（assets/models/face_detection_yunet.onnx）")
    try:
        import cv2
    except ImportError:
        raise HTTPException(status_code=400, detail="服务器缺少 opencv-python-headless，无法做人脸检测")

    def _blur():
        cap = cv2.VideoCapture(src_path)
        if not cap.isOpened():
            raise RuntimeError("无法读取视频")
        fps = cap.get(cv2.CAP_PROP_FPS) or 25
        width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        detector = cv2.FaceDetectorYN_create(model_path, "", (width, height), 0.6, 0.3, 5000)
        tmp_path = src_path + ".blur_tmp.avi"
        writer = cv2.VideoWriter(tmp_path, cv2.VideoWriter_fourcc(*'MJPG'), fps, (width, height))
        faces_total = 0
        frames = 0
        while True:
            ok, frame = cap.read()
            if not ok:
                break
            frames += 1
            _, faces = detector.detect(frame)
            if faces is not None and len(faces):
                faces_total += len(faces)
                for face in faces:
                    x, y, w, h = [int(v) for v in face[:4]]
                    pad_x = int(w * 0.15); pad_y = int(h * 0.25)
                    x0 = max(0, x - pad_x); y0 = max(0, y - pad_y)
                    x1 = min(width, x + w + pad_x); y1 = min(height, y + h + pad_y)
                    roi = frame[y0:y1, x0:x1]
                    if roi.size:
                        frame[y0:y1, x0:x1] = cv2.GaussianBlur(roi, (ks, ks), 0)
            writer.write(frame)
        cap.release()
        writer.release()
        out_filename = f"blurred_{uuid.uuid4().hex[:12]}.mp4"
        out_path = output_path_for(out_filename, "input")
        subprocess.run(
            ["ffmpeg", "-y", "-i", tmp_path, "-c:v", "libx264", "-preset", "fast",
             "-crf", "20", "-pix_fmt", "yuv420p", "-movflags", "+faststart", out_path],
            check=True, capture_output=True)
        try:
            os.remove(tmp_path)
        except OSError:
            pass
        return out_filename, out_path, frames, faces_total

    try:
        out_filename, out_path, frames, faces_total = await asyncio.to_thread(_blur)
    except subprocess.CalledProcessError as exc:
        raise HTTPException(status_code=500, detail=f"视频编码失败：{(exc.stderr or b'').decode('utf-8', errors='replace')[:300]}")
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"人脸模糊处理失败：{exc}")
    return {
        "url": output_url_for(out_filename, "input"),
        "name": f"模糊人脸_{uuid.uuid4().hex[:6]}.mp4",
        "kind": "video",
        "frames": frames,
        "faces_detected": faces_total,
    }


class ImageMattingRequest(BaseModel):
    url: str = ""            # 本地图片 URL（/assets/ 或 /output/ 开头）
    mode: str = "api"        # api=生图API绿幕抠图（默认）；local=本地 RMBG-2.0 推理


_MATTING_MODEL_PATH = os.path.join(BASE_DIR, "assets", "models", "rmbg_2.0.onnx")
_MATTING_MODEL_URL = "https://modelscope.cn/models/briaai/RMBG-2.0/resolve/master/onnx/model_quantized.onnx"
_MATTING_MODEL_SIZE = 366087549  # 量化版约 349MB，用于无 Content-Length 时的进度估算
_OLD_MATTING_MODEL_PATH = os.path.join(BASE_DIR, "assets", "models", "rmbg_1.4.onnx")
_MATTING_SESSION = None
_MODEL_DOWNLOAD_TASKS = {}


def _cleanup_old_matting_model():
    if os.path.isfile(_OLD_MATTING_MODEL_PATH):
        try:
            os.remove(_OLD_MATTING_MODEL_PATH)
            print(f"[Matting] 已删除旧版 RMBG-1.4 模型：{_OLD_MATTING_MODEL_PATH}")
        except OSError:
            pass


def _matting_session():
    """RMBG-2.0 抠图推理会话（单例缓存）。模型未下载时返回 None，由接口层决定报 400。"""
    global _MATTING_SESSION
    if _MATTING_SESSION is not None:
        return _MATTING_SESSION
    if not os.path.isfile(_MATTING_MODEL_PATH):
        return None
    try:
        import onnxruntime
    except ImportError:
        return None
    sess = onnxruntime.InferenceSession(_MATTING_MODEL_PATH, providers=["CPUExecutionProvider"])
    _MATTING_SESSION = sess
    _cleanup_old_matting_model()
    return sess


def run_image_matting(src_path: str, out_path: str):
    """本地 RMBG-2.0 抠图：读图 → 1024 推理 → mask 回放 → alpha 拉伸/腐蚀/羽化 + 边缘去边 → 透明 PNG。"""
    import numpy as np
    import cv2
    img = Image.open(src_path).convert("RGB")
    orig_w, orig_h = img.size
    img_1024 = img.resize((1024, 1024), Image.BILINEAR)
    arr = np.array(img_1024).astype(np.float32) / 255.0
    arr = (arr - np.array([0.485, 0.456, 0.406], np.float32)) / np.array([0.229, 0.224, 0.225], np.float32)
    arr = arr.transpose(2, 0, 1)[None]
    sess = _matting_session()
    if sess is None:
        raise RuntimeError("本地抠图模型未下载")
    out = sess.run(None, {sess.get_inputs()[0].name: arr})[-1]
    mask = out[0, 0]  # 此 ONNX 导出已内置 sigmoid（实测输出 ∈ [0,1]），勿再重复加
    # 回放原尺寸（LANCZOS 保留更多细节）
    mask_img = Image.fromarray((mask * 255).astype(np.uint8)).resize((orig_w, orig_h), Image.LANCZOS)
    alpha = np.array(mask_img).astype(np.float32) / 255.0
    # 1) alpha 拉伸：低阈值保留弱响应细节（鞋头/鞋带/反光），主体顶到 1，消除"纱感"与大面积半透明
    alpha = np.clip((alpha - 0.12) / 0.70, 0.0, 1.0)
    # 2) 轻微腐蚀 + 高斯羽化：边缘向主体内收缩，去掉背景残留圈（腐蚀仅1次，避免啃掉主体细节）
    a8 = (alpha * 255).astype(np.uint8)
    a8 = cv2.erode(a8, np.ones((3, 3), np.uint8), iterations=1)
    a_blur = cv2.GaussianBlur(a8.astype(np.float32), (0, 0), 0.8)
    alpha = np.clip(a_blur / 255.0, 0.0, 1.0)
    # 3) 颜色反污染 defringe（方案A）：对半透明带 alpha 0.02~0.98 统一反推前景真实色
    #    F=(I-(1-a)*B)/a，B 为背景色估计；消除背景色光晕（黑底白边/灰边），覆盖主体侧过渡带
    rgb_u8 = np.array(img).astype(np.uint8)
    edge = (alpha > 0.02) & (alpha < 0.98)
    if edge.any():
        # 3a) 背景色估计图：把主体区域(alpha>0.5)抹掉，用周围背景 inpaint 填充，得到逐像素背景色 B
        body_mask = ((alpha > 0.5) * 255).astype(np.uint8)
        bg_est = cv2.inpaint(rgb_u8, body_mask, 15, cv2.INPAINT_TELEA).astype(np.float32)
        # 3b) 颜色反污染：反推前景真实色，clip 后轻微中值平滑去噪
        a_e = np.clip(alpha[edge], 1e-6, 1.0)[:, None]
        F = (rgb_u8.astype(np.float32)[edge] - (1.0 - a_e) * bg_est[edge]) / a_e
        F_u8 = np.clip(F, 0, 255).astype(np.uint8)
        F_u8 = cv2.medianBlur(F_u8, 3)
        rgb_u8[edge] = F_u8
    rgb = rgb_u8.astype(np.float32)
    rgba = np.zeros((orig_h, orig_w, 4), dtype=np.float32)
    rgba[:, :, :3] = rgb
    rgba[:, :, 3] = alpha * 255.0
    Image.fromarray(rgba.astype(np.uint8)).save(out_path)


def _matting_model_downloaded() -> bool:
    return os.path.isfile(_MATTING_MODEL_PATH) and os.path.getsize(_MATTING_MODEL_PATH) > 300 * 1024 * 1024


def _download_matting_model(task_id: str):
    """后台下载 RMBG-2.0 模型：流式写 .tmp，下完 rename（防半截文件），进度写入 _MODEL_DOWNLOAD_TASKS。"""
    task = _MODEL_DOWNLOAD_TASKS[task_id]
    tmp_path = _MATTING_MODEL_PATH + ".tmp"
    for attempt in (1, 2):
        try:
            with requests.get(_MATTING_MODEL_URL, stream=True, timeout=(30, 120)) as resp:
                resp.raise_for_status()
                total = int(resp.headers.get("Content-Length") or 0) or _MATTING_MODEL_SIZE
                downloaded = 0
                os.makedirs(os.path.dirname(_MATTING_MODEL_PATH), exist_ok=True)
                with open(tmp_path, "wb") as f:
                    for chunk in resp.iter_content(chunk_size=1024 * 1024):
                        if chunk:
                            f.write(chunk)
                            downloaded += len(chunk)
                            task["progress"] = min(99, int(downloaded * 100 / total))
            if os.path.getsize(tmp_path) <= 300 * 1024 * 1024:
                raise RuntimeError("模型文件不完整")
            os.replace(tmp_path, _MATTING_MODEL_PATH)
            _cleanup_old_matting_model()
            task.update({"downloading": False, "progress": 100, "done": True})
            print(f"[Matting] 本地抠图模型下载完成：{_MATTING_MODEL_PATH}")
            return
        except Exception as exc:
            task["error"] = str(exc)[:200]
            print(f"[Matting] 模型下载失败（第 {attempt} 次）: {exc}")
            try:
                os.remove(tmp_path)
            except OSError:
                pass
    task["downloading"] = False


@app.get("/api/matting/model/status")
async def matting_model_status():
    """本地抠图模型状态：是否已下载、下载进度。"""
    task = _MODEL_DOWNLOAD_TASKS.get("matting_model_download") or {}
    downloaded = _matting_model_downloaded()
    return {
        "downloaded": downloaded,
        "model_size_mb": 349,
        "downloading": bool(task.get("downloading")),
        "progress": 100 if downloaded else int(task.get("progress") or 0),
        "error": task.get("error") or "",
    }


@app.post("/api/matting/model/download")
async def matting_model_download():
    """下载本地抠图模型（RMBG-2.0 量化版，约 349MB）。已在下载/已下载时直接返回，不重复下载。"""
    task_id = "matting_model_download"
    task = _MODEL_DOWNLOAD_TASKS.get(task_id)
    if task and task.get("downloading"):
        return {"ok": True, "task_id": task_id, "already": True}
    if _matting_model_downloaded():
        return {"ok": True, "downloaded": True}
    _MODEL_DOWNLOAD_TASKS[task_id] = {"downloading": True, "progress": 0, "error": "", "done": False}
    Thread(target=_download_matting_model, args=(task_id,), daemon=True).start()
    return {"ok": True, "task_id": task_id}


