    """弹出原生文件夹选择对话框，返回所选路径。"""
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk()
        root.withdraw()
        root.attributes("-topmost", True)
        folder = filedialog.askdirectory(title="选择输出目录")
        root.destroy()
        if folder:
            return {"path": os.path.abspath(folder)}
        return {"path": ""}
    except Exception:
        return {"path": ""}

