@app.get("/api/personas")
async def get_personas():
    """列出全部系统角色（内置 + 用户自建）。"""
    return public_persona_library()

@app.post("/api/personas")
async def create_persona(payload: PersonaRequest):
    """新建用户角色。"""
    content = str(payload.content or "").strip()
    if not content:
        raise HTTPException(status_code=400, detail="角色提示词内容不能为空")
    data = load_persona_library()
    item = normalize_persona_item({
        "id": f"persona_{uuid.uuid4().hex[:12]}",
        "name": payload.name,
        "description": payload.description,
        "content": content,
        "builtin": False,
        "created_at": now_ms(),
        "updated_at": now_ms(),
    })
    item["builtin"] = False
    data.setdefault("personas", []).append(item)
    data = save_persona_library(data)
    result = public_persona_library(data)
    result["persona"] = item
    return result

@app.patch("/api/personas/{persona_id}")
async def update_persona(persona_id: str, payload: PersonaRequest):
    """更新用户自建角色；内置角色拒绝修改（提示改用「另存为」）。"""
    data = load_persona_library()
    item = find_persona(data, persona_id)
    if not item:
        raise HTTPException(status_code=404, detail="角色不存在")
    if item.get("builtin"):
        raise HTTPException(status_code=400, detail="内置角色不可修改，请使用「另存为」创建新角色")
    next_name = str(payload.name or "").strip() or item.get("name")
    next_desc = str(payload.description or "").strip() or item.get("description")
    next_content = str(payload.content or "").strip() or item.get("content")
    next_item = normalize_persona_item({
        **item,
        "id": persona_id,
        "name": next_name,
        "description": next_desc,
        "content": next_content,
        "builtin": False,
        "updated_at": now_ms(),
    })
    next_item["builtin"] = False
    personas = data.get("personas") or []
    for index, existing in enumerate(personas):
        if isinstance(existing, dict) and existing.get("id") == persona_id:
            personas[index] = next_item
            break
    data["personas"] = personas
    data = save_persona_library(data)
    result = public_persona_library(data)
    result["persona"] = next_item
    return result

@app.delete("/api/personas/{persona_id}")
async def delete_persona(persona_id: str):
    """删除用户自建角色；内置角色拒绝删除。"""
    data = load_persona_library()
    item = find_persona(data, persona_id)
    if not item:
        raise HTTPException(status_code=404, detail="角色不存在")
    if item.get("builtin"):
        raise HTTPException(status_code=400, detail="内置角色不可删除")
    personas = data.get("personas") or []
    kept = [p for p in personas if not (isinstance(p, dict) and p.get("id") == persona_id)]
    data["personas"] = kept
    data = save_persona_library(data)
    result = public_persona_library(data)
    result["removed"] = 1
    return result

# ── 长期记忆库（memory）· CRUD ──────────────────────────────────────────
# 记忆由服务端在请求时自动注入 system prompt；前端仅做管理 UI，不参与 textarea。
# 记忆全部由用户管理（无内置条目），每条带 enabled 开关（默认开）。

@app.get("/api/memories")
async def get_memories():
    """列出全部长期记忆。"""
    return public_memory_library()

@app.post("/api/memories")
async def create_memory(payload: MemoryRequest):
    """新增一条长期记忆（默认启用）。"""
    content = str(payload.content or "").strip()
    if not content:
        raise HTTPException(status_code=400, detail="记忆内容不能为空")
    data = load_memory_library()
    item = normalize_memory_item({
        "id": f"memory_{uuid.uuid4().hex[:12]}",
        "content": content,
        "enabled": True,
        "scope": payload.scope,
        "conversation_id": payload.conversation_id,
        "created_at": now_ms(),
        "updated_at": now_ms(),
    })
    data.setdefault("memories", []).append(item)
    data = save_memory_library(data)
    result = public_memory_library(data)
    result["memory"] = item
    return result

@app.patch("/api/memories/{memory_id}")
async def update_memory(memory_id: str, payload: MemoryRequest):
    """更新记忆（内容 / 启用开关）。"""
    data = load_memory_library()
    item = find_memory(data, memory_id)
    if not item:
        raise HTTPException(status_code=404, detail="记忆不存在")
    next_content = str(payload.content or "").strip() or item.get("content")
    next_enabled = bool(item.get("enabled", True)) if payload.enabled is None else bool(payload.enabled)
    next_scope = payload.scope if payload.scope in ("global", "conversation") else item.get("scope", "global")
    next_conversation_id = payload.conversation_id if payload.scope == "conversation" else item.get("conversation_id", "")
    next_item = normalize_memory_item({
        **item,
        "id": memory_id,
        "content": next_content,
        "enabled": next_enabled,
        "scope": next_scope,
        "conversation_id": next_conversation_id,
        "updated_at": now_ms(),
    })
    memories = data.get("memories") or []
    for index, existing in enumerate(memories):
        if isinstance(existing, dict) and existing.get("id") == memory_id:
            memories[index] = next_item
            break
    data["memories"] = memories
    data = save_memory_library(data)
    result = public_memory_library(data)
    result["memory"] = next_item
    return result

@app.delete("/api/memories/{memory_id}")
async def delete_memory(memory_id: str):
    """删除一条长期记忆。"""
    data = load_memory_library()
    item = find_memory(data, memory_id)
    if not item:
        raise HTTPException(status_code=404, detail="记忆不存在")
    memories = data.get("memories") or []
    kept = [m for m in memories if not (isinstance(m, dict) and m.get("id") == memory_id)]
    data["memories"] = kept
    data = save_memory_library(data)
    result = public_memory_library(data)
    result["removed"] = 1
    return result



async def caption_image_with_provider(abs_path, prompt, provider_id, model, ms_model=""):
    llm_provider = get_api_provider(provider_id) if provider_id not in ("modelscope",) else {}
    if is_codex_provider(llm_provider):
        resolved_model = selected_model(model, (llm_provider.get("chat_models") or CODEX_DEFAULT_CHAT_MODELS)[0])
        payload = CanvasLLMRequest(
            message=(prompt or "描述图片").strip() or "描述图片",
            provider=provider_id or "codex",
            model=resolved_model,
            images=[abs_path],
        )
        text, _raw = await codex_chat_text(payload, [])
        return text, resolved_model
    if is_gemini_cli_provider(llm_provider):
        resolved_model = selected_model(model, (llm_provider.get("chat_models") or GEMINI_CLI_DEFAULT_CHAT_MODELS)[0])
        payload = CanvasLLMRequest(
            message=(prompt or "描述图片").strip() or "描述图片",
            provider=provider_id or "gemini-cli",
            model=resolved_model,
            images=[abs_path],
        )
        text, _raw = await gemini_cli_chat_text(payload, [])
        return text, resolved_model
    chat_base, chat_hdrs, resolved_model = resolve_chat_provider(provider_id, model, ms_model)
    is_apimart = is_apimart_provider(llm_provider)
    prompt_text = (prompt or "描述图片").strip() or "描述图片"
    data_url = image_path_to_data_url(abs_path, max_size=1024)
    messages = [{
        "role": "user",
        "content": [
            {"type": "text", "text": prompt_text},
            {"type": "image_url", "image_url": {"url": data_url}},
        ],
    }]
    raw = None
    try:
        async with httpx.AsyncClient(http2=False, verify=_SSL_CONTEXT, trust_env=_TRUST_ENV, timeout=AI_REQUEST_TIMEOUT) as client:
            req_body = {"model": resolved_model, "messages": messages}
            if is_apimart:
                req_body["stream"] = False
            response = await client.post(
                f"{chat_base}/chat/completions",
                headers=chat_hdrs,
                json=req_body,
            )
            response.raise_for_status()
            raw = response.json()
    except httpx.HTTPStatusError as exc:
        body = exc.response.text or ""
        friendly = friendly_chat_error_detail(body, resolved_model, llm_provider)
        raise HTTPException(status_code=exc.response.status_code, detail=friendly or f"上游接口错误：{body}") from exc
    except httpx.HTTPError as exc:
        log_net_error(f"对话 网络/TLS错误 provider={llm_provider} model={resolved_model}", exc)
        raise HTTPException(status_code=502, detail=f"请求上游接口失败：{exc}") from exc
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=502, detail=f"解析上游响应失败：{exc}") from exc
    text = text_from_chat_response(raw).strip() if isinstance(raw, dict) else ""
    return text or "接口返回了空回复。", resolved_model


def find_asset_item_in_library(lib, item_id, library_id=""):
    for library in lib.get("libraries", []):
        if library_id and library.get("id") != library_id:
            continue
        for cat in library.get("categories", []):
            for item in cat.get("items", []):
                if item.get("id") == item_id:
                    return item
    return None


@app.put("/api/canvases/{canvas_id}")
async def update_canvas(canvas_id: str, payload: CanvasSaveRequest):
    canvas = load_canvas(canvas_id)
    current_updated_at = int(canvas.get("updated_at") or 0)
    if payload.base_updated_at and current_updated_at and int(payload.base_updated_at) < current_updated_at:
        raise HTTPException(status_code=409, detail={
            "message": "画布已被其他页面更新，已拒绝旧版本覆盖。",
            "canvas": canvas,
            "updated_at": current_updated_at,
        })
    canvas["title"] = (payload.title or canvas.get("title") or "未命名画布")[:80]
    canvas["icon"] = (payload.icon or canvas.get("icon") or "layers")[:32]
    canvas["kind"] = normalize_canvas_kind(canvas.get("kind"))
    canvas["nodes"] = payload.nodes
    canvas["connections"] = payload.connections
    if canvas["kind"] == "smart":
        canvas["viewport"] = payload.viewport
    else:
        canvas["viewport"] = canvas.get("viewport") or {"x": 0, "y": 0, "scale": 1}
    canvas["logs"] = payload.logs[-500:]
    canvas["settings"] = payload.settings or {}
    save_canvas(canvas)
    # V2 Phase 2：旁路保存完整画布状态为版本快照（保留最近 N 个，失败不影响主流程）
    snapshot_canvas_version(canvas)
    await manager.broadcast_canvas_updated(canvas_id, int(canvas.get("updated_at") or now_ms()), payload.client_id)
    return {"canvas": canvas}

@app.delete("/api/canvases/{canvas_id}")
async def delete_canvas(canvas_id: str):
    canvas = load_canvas_any(canvas_id)
    if not canvas.get("deleted_at"):
        canvas["deleted_at"] = now_ms()
        save_canvas(canvas)
    return {"ok": True}

@app.post("/api/canvases/{canvas_id}/restore")
async def restore_canvas(canvas_id: str):
    canvas = load_canvas_any(canvas_id)
    if canvas.get("deleted_at"):
        canvas.pop("deleted_at", None)
        save_canvas(canvas)
    return {"canvas": canvas}

@app.delete("/api/canvases/{canvas_id}/purge")
async def purge_canvas(canvas_id: str):
    path = canvas_path(canvas_id)
    if os.path.exists(path):
        os.remove(path)
    return {"ok": True}

# --- V2 Phase 2: 画布版本化 API ---

@app.get("/api/canvases/{canvas_id}/versions")
async def list_canvas_versions_api(canvas_id: str):
    load_canvas(canvas_id)  # 404 校验（含软删除）
    return {"versions": list_canvas_versions(canvas_id), "limit": CANVAS_VERSION_LIMIT}

@app.get("/api/canvases/{canvas_id}/versions/{version}")
async def get_canvas_version_api(canvas_id: str, version: int):
    load_canvas(canvas_id)
    return read_canvas_version(canvas_id, version)

@app.post("/api/canvases/{canvas_id}/versions/{version}/restore")
async def restore_canvas_version_api(canvas_id: str, version: int, request: Request):
    canvas = load_canvas(canvas_id)
    rec = read_canvas_version(canvas_id, version)
    snapshot = rec.get("canvas_snapshot")
    if not isinstance(snapshot, dict):
        raise HTTPException(status_code=400, detail="版本快照损坏")
    # 用快照覆盖画布内容；保留当前画布的身份/归属字段（id/创建时间/项目/负责人/颜色/置顶/位置）
    restored = dict(snapshot)
    for key in ("id", "created_at", "project", "owner", "color", "pinned", "board_x", "board_y", "deleted_at"):
        if key in canvas:
            restored[key] = canvas[key]
    restored["kind"] = canvas.get("kind") or restored.get("kind") or "classic"
    save_canvas(restored)
    note = f"restored from v{version}"
    new_version = snapshot_canvas_version(restored, note=note)
    client_id = ""
    try:
        body = await request.json()
        client_id = str((body or {}).get("client_id") or "")
    except Exception:
        pass
    await manager.broadcast_canvas_updated(canvas_id, int(restored.get("updated_at") or now_ms()), client_id)
    return {"canvas": restored, "version": new_version, "note": note}

@app.delete("/api/canvases/{canvas_id}/versions/{version}")
async def delete_canvas_version_api(canvas_id: str, version: int):
    load_canvas(canvas_id)
    path = os.path.join(canvas_versions_dir(canvas_id), f"v{int(version)}.json")
    if not os.path.exists(path):
        raise HTTPException(status_code=404, detail="版本不存在")
    with CANVAS_LOCK:
        os.remove(path)
    return {"ok": True}

